content:
1040                  }
  1041                  o4 = slen * sizeof(uint32_t);
  1042                  if (inp[i].pi_type & (CDF_ARRAY|CDF_BYREF|CDF_RESERVED))
  1043                       goto unknown;
  1044                  switch (inp[i].pi_type & CDF_TYPEMASK) {
  1045                  case CDF_NULL:
  1046                  case CDF_EMPTY:
  1047                       break;
  1048                  case CDF_SIGNED16:
  1049                       if (!cdf_copy_info(&inp[i], &q[o4], e, sizeof(int16_t)))
  1050                          goto unknown;
  1051                       break;
  1052                  case CDF_SIGNED32:
  1053                  case CDF_BOOL:
  1054                  case CDF_UNSIGNED32:
  1055                  case CDF_FLOAT:
  1056                       if (!cdf_copy_info(&inp[i], &q[o4], e, sizeof(int32_t)))
  1057                          goto unknown;
  1058                       break;
  1059                  case CDF_SIGNED64:
  1060                  case CDF_UNSIGNED64:
  1061                  case CDF_DOUBLE:
  1062                  case CDF_FILETIME:
  1063                       if (!cdf_copy_info(&inp[i], &q[o4], e, sizeof(int64_t)))
  1064                          goto unknown;
  1065                       break;
  1066                  case CDF_LENGTH32_STRING:
  1067                  case CDF_LENGTH32_WSTRING:
  1068                       if (nelements > 1) {
  1069                          size_t nelem = inp - *info;
  1070                          inp = cdf_grow_info(info, maxcount, nelements);
  1071                          if (inp == NULL)
  1072                                  goto out;
  1073                          inp += nelem;
  1074                       }
  1075                       for (j = 0; j < nelements && i < sh.sh_properties;
  1076                           j++, i++)
  1077                       {
  1078                          uint32_t l;
  1079
  1080                          if (o4 + sizeof(uint32_t) > left)
  1081                                  goto out;
  1082
  1083                          l = CDF_GETUINT32(q, slen);
  1084                          o4 += sizeof(uint32_t);
  1085                          if (o4 + l > left)
  1086                                  goto out;
  1087
  1088                          inp[i].pi_str.s_len = l;
  1089                          inp[i].pi_str.s_buf = CAST(const char *,
  1090                              CAST(const void *, &q[o4]));
  1091
  1092                          DPRINTF(("o=%" SIZE_T_FORMAT "u l=%d(%"
  1093                              SIZE_T_FORMAT "u), t=%" SIZE_T_FORMAT
  1094                              "u s=%s\n", o4, l, CDF_ROUND(l, sizeof(l)),
  1095                              left, inp[i].pi_str.s_buf));
  1096
  1097                          if (l & 1)
  1098                                  l++;
  1099
  1100                          slen += l >> 1;
  1101                          o4 = slen * sizeof(uint32_t);
  1102                       }
  1103                       i--;
  1104                       break;
  1105                  case CDF_CLIPBOARD:
  1106                       if (inp[i].pi_type & CDF_VECTOR)
  1107                          goto unknown;
  1108                       break;
  1109                  default:
  1110                  unknown:
  1111                       memset(&inp[i].pi_val, 0, sizeof(inp[i].pi_val));
  1112                       DPRINTF(("Don't know how to deal with %#x\n",
  1113                           inp[i].pi_type));
  1114                       break;
  1115                  }
  1116          }
  1117          return 0;
  1118  out:
  1119          free(*info);
  1120          *info = NULL;
  1121          *count = 0;
  1122          *maxcount = 0;
  1123          errno = EFTYPE;
  1124          return -1;
  1125  }
